<?php
// CLI-only one-time migration. Run after the PHP service has created its PostgreSQL schema.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$src=__DIR__.'/ksiva.sqlite'; if(!is_file($src)){fwrite(STDERR,"Не найден migration/ksiva.sqlite\n");exit(1);}
$dsn=getenv('DATABASE_URL')?:'';if(!$dsn){fwrite(STDERR,"Задай DATABASE_URL\n");exit(1);}
if(str_starts_with($dsn,'postgres://')||str_starts_with($dsn,'postgresql://')){$u=parse_url($dsn);$pgdsn='pgsql:host='.$u['host'].';port='.($u['port']??5432).';dbname='.ltrim($u['path'],'/').';sslmode=require';$user=$u['user']??'';$pass=$u['pass']??'';}else{$pgdsn=$dsn;$user=getenv('DB_USER')?:'';$pass=getenv('DB_PASSWORD')?:'';}
try{$old=new PDO('sqlite:'.$src,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pg=new PDO($pgdsn,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){fwrite(STDERR,"Подключение не удалось: ".$e->getMessage()."\n");exit(1);}
$tables=['gifts','nominations','nomination_descriptions','users','candidates','settings','votes','archives','chat_messages','user_gifts','private_messages','friendships'];$total=0;$pg->beginTransaction();try{foreach($tables as $table){$exists=$old->query("SELECT name FROM sqlite_master WHERE type='table' AND name=".$old->quote($table))->fetch();if(!$exists)continue;$cols=$old->query('PRAGMA table_info("'.$table.'")')->fetchAll();$names=array_column($cols,'name');$rows=$old->query('SELECT * FROM "'.$table.'"')->fetchAll();foreach($rows as $row){$use=array_intersect(array_keys($row),$names);if(!$use)continue;$quoted=implode(',',array_map(fn($c)=>'"'.$c.'"',$use));$marks=implode(',',array_fill(0,count($use),'?'));$sql='INSERT INTO "'.$table.'" ('.$quoted.') VALUES ('.$marks.') ON CONFLICT DO NOTHING';$st=$pg->prepare($sql);$st->execute(array_map(fn($c)=>$row[$c],$use));$total+=$st->rowCount();}echo "$table: ".count($rows)." rows read\n";}$pg->commit();echo "Готово. Импортировано строк: $total\n";}catch(Throwable $e){if($pg->inTransaction())$pg->rollBack();fwrite(STDERR,"Импорт отменён: ".$e->getMessage()."\n");exit(1);}
